function dividir(a, b) {
  if (!Number.isFinite(a) || !Number.isFinite(b)) {
    throw new TypeError('Se esperan números finitos');
  }
  if (b === 0) throw new RangeError('División entre cero');
  return a / b;
}
console.assert(dividir(8, 2) === 4);
try { dividir(1, 0); } catch (error) { console.log(error.message); }

