public class Promedios {
 static double media(int[] notas) {
  if (notas.length == 0) throw new IllegalArgumentException("Array vacío");
  int suma = 0;
  for (int nota : notas) suma += nota;
  return (double) suma / notas.length;
 }
 public static void main(String[] args) {
  System.out.println(media(new int[] {7, 8, 9}));
 }
}

